mutants.source:
def compound(principal, rate, years):
    balance = principal
    for year in range(years):
        balance = balance * (1 + rate)
    return balance

def compound(principal, rate, years):
    balance = principal
    for year in range(max(years, 1)):
        balance = balance * (1 + rate)
    return round(balance, 2)
